export function findAndReplaceKey(data, key, value, replacementKey, text) {
  /*
    data => Question object
    key => key of question that needs to be match, e.g, name
    value => value that is to be matched, e.g., label of reponse
    replaceKey => key whose value needs to be replace e.g., default_answer
    text => value that is to be replaces e.g., value of response provided
  */
  if (data[key] === value) {
    data[replacementKey] = text
  } else {
    if (!data['child_questions'][data['default_answer']]) {
      findAndReplaceKey(data['child_questions'][Object.keys(data['child_questions'])[0]], key, value, replacementKey, text)
    } else {
      findAndReplaceKey(data['child_questions'][data['default_answer']], key, value, replacementKey, text)
    }
  }
}

export function getResponseKey(data, responses, label = 'name') {
  responses[data[label]] = data['default_answer']
  if (Object.keys(data['child_questions']).length === 0 || !data['child_questions'][data['default_answer']]) {
    return responses
  } else {
    if (data['child_questions'][data['default_answer']]) {
      getResponseKey(data['child_questions'][data['default_answer']], responses, label)
    }
  }
}

export function generatepolicyFormAttributeMultipleProduct(policyFormAttributeMultipleProduct) {
  let array = []
  for (const key in policyFormAttributeMultipleProduct) {

    const product = policyFormAttributeMultipleProduct[key]

    let options

    for (const formType in product) {
      const form = product[formType]

      options = Object.keys(form).map((key) => ({
        value: `${formType}.${key}`,
        label: `${formType}.${key}`
      }))
    }

    const group = {
      label: key,
      options
    }
    array.push(group)
  }
  return array
}
