import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Radio, Spin, Button, Row, notification, Empty, Divider } from 'antd'
import moment from 'moment'
import _ from 'lodash'
import { ChooseTemplateStyle } from './index.style'
import ClaimsAction from '../../../../redux/claims/actions'
import LoadingActions from '../../../../../redux/loading/actions'
import ErrorActions from '../../../../../redux/error/actions'

const RadioGroup = Radio.Group

const { getConfigTemplates, getConfigTemplateDetails } = ClaimsAction
const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions

class ChooseTemplate extends Component {
  state = {
    template: 1
  }

  componentDidMount() {
    // const { configSource = '' } = this.props
    // this.props.getConfigTemplates(({ query: { source: configSource } }))
    // this.props.resetLoadingRedux(['GET_CONFIG_TEMPLATES_DETAILS'])
    // this.props.resetErrorRedux(['GET_CONFIG_TEMPLATES_DETAILS'])
  }
  
  

  UNSAFE_componentWillReceiveProps(nextProps) {
    const {
      getConfigTemplateDetailsLoading,
      getConfigTemplateDetailsError,
      claimConfigTemplate
    } = nextProps

    if (claimConfigTemplate && claimConfigTemplate.length) {
      const { id } = claimConfigTemplate[0]
      this.setState({
        template: id
      })
    }

    if (getConfigTemplateDetailsLoading === false) {
      if (getConfigTemplateDetailsError === false) {
        this.props.handleNext()
      }
      this.props.resetLoadingRedux(['GET_CONFIG_TEMPLATES_DETAILS'])
      this.props.resetErrorRedux(['GET_CONFIG_TEMPLATES_DETAILS'])
    }
  }

  handleChange = (e) => {
    this.setState({ template: e.target.value })
  }

  onHandleNext = () => {
    const { inprogressConfig } = this.props
    const { template } = this.state
    if (!template) {
      notification['error']({ message: 'Please select template!' })
    }
    if (typeof template === 'string') {
      const id = template.split('-')[1]
      let configDump = _.find(inprogressConfig, { 'config_dump_id': parseInt(id) })
      this.props.handleInprogressConfigData(configDump)
    } else {
      this.props.getConfigTemplateDetails({
        query: {
          templateId: template
        }
      })
    }
  }

  render() {
    const { claimConfigTemplateLoading, claimConfigTemplate, getConfigTemplateDetailsLoading,
      inprogressConfig = [], inprogressConfigLoading, edit
    } = this.props
    const { template } = this.state

    return (
      <ChooseTemplateStyle>
        <Spin spinning={!!claimConfigTemplateLoading || !!getConfigTemplateDetailsLoading || !!inprogressConfigLoading}>
          <div className='heading'>
            Templates
          </div>
          {
            claimConfigTemplate.length
              ? <RadioGroup
                value={template}
                onChange={this.handleChange}
              >
                {
                  claimConfigTemplate.map(({ id, label, description }) =>
                    <Row type='flex' justify='start' align='middle' key={id}>
                      <Radio value={id} />
                      <div>
                        <div className='label'>{label}</div>
                        <div className='description'>{description}</div>
                      </div>
                    </Row>
                  )
                }
                {
                  (!edit && inprogressConfig.length > 0) &&
                  <div>
                    <Divider />
                    <div className='heading'>
                      Existing Dumps
                    </div>
                    {
                      inprogressConfig.map(({ config_dump_id: id, created_by: createdBy, created_at: createdAt, updated_at: updatedAt }) =>
                        <Row type='flex' justify='start' align='middle' key={id}>
                          <Radio value={`dump-${id}`} />
                          <div>
                            <div className='label'>{id}</div>
                            <div className='description'>Created By - {createdBy}</div>
                            <div className='description'>Created At - {moment(createdAt).format('lll')}</div>
                            <div className='description'>Updated At - {moment(updatedAt).format('lll')}</div>
                          </div>
                        </Row>
                      )
                    }
                  </div>
                }
              </RadioGroup>
              : <Empty />
          }
          <Row type='flex' justify='end'>
            <Button
              type='primary'
              onClick={this.onHandleNext}
              disabled={!template}
            >
              Next
            </Button>
          </Row>
        </Spin>
      </ChooseTemplateStyle>
    )
  }
}

export default connect(state => ({
  claimConfigTemplateLoading: state.Loading.GET_CONFIG_TEMPLATES,
  claimConfigTemplate: state.Claims.claimConfigTemplate,

  getConfigTemplateDetailsLoading: state.Loading.GET_CONFIG_TEMPLATES_DETAILS,
  getConfigTemplateDetailsError: state.Error.GET_CONFIG_TEMPLATES_DETAILS,

  inprogressConfig: state.Claims.inprogressConfig,
  inprogressConfigLoading: state.Loading.GET_INPROGRESS_CONFIG
}), {
  getConfigTemplates,
  getConfigTemplateDetails,
  resetLoadingRedux,
  resetErrorRedux
})(ChooseTemplate)
