import React from 'react'
import { Checkbox, Row, Select, Input } from 'antd'

const { Option } = Select

export const FormColumns = (props) => [{
  title: 'Title',
  dataIndex: 'title',
  key: 'title'
}, {
  title: 'Action',
  dataIndex: 'id',
  key: 'action',
  render: (id, data, index) => (
    <Row type='flex'>
      <div onClick={() => props.editForm(data, index)} className='edit'>Edit</div>
      <div onClick={() => props.deleteForm(index)} className='delete'>Delete</div>
    </Row>
  )
}]

export const SelectedAttributesColumns = (props, regexList = []) => [{
  title: 'Label',
  dataIndex: 'label',
  key: 'label',
  render: (value, _, index) => <Input
    className='input-label'
    defaultValue={value}
    onChange={(e) => props.handleChangeLabel(index, e.target.value)}
                               />
}, {
  title: 'Mandatory',
  key: 'required',
  dataIndex: 'required',
  render: (value, _row, index) => <Checkbox defaultChecked={value} onChange={(e) => props.handleCheckboxChange(index, 'required', e.target.checked)} />
}, {
  title: 'Document Verification Required',
  key: 'validation_required',
  dataIndex: 'validation_required',
  render: (value, _row, index) => <Checkbox defaultChecked={value} onChange={(e) => props.handleCheckboxChange(index, 'validation_required', e.target.checked)} />
}, {
  title: 'Mulitple Value Required',
  key: 'is_multiple_value_required',
  dataIndex: 'is_multiple_value_required',
  render: (value, rowData, index) => ['image', 'choices'].includes(rowData.type) &&
    <Checkbox
      defaultChecked={value}
      onChange={(e) => props.handleCheckboxChange(index, 'is_multiple_value_required', e.target.checked)}
    />
}, {
  title: 'Type',
  key: 'type',
  dataIndex: 'type'
}, {
  title: 'Internal',
  key: 'is_internal',
  dataIndex: 'is_internal',
  render: (value) => value.toString()
},
{
  title: 'Regex validation (optional)',
  key: 'regex',
  dataIndex: 'regex',
  // render: (value, rowData, index) => {
  //   if (!value) {
  //     return <div>hasduha</div>
  //   }
  //   return (['string', 'text'].includes(rowData['type']) ?
  //     <Select
  //       allowClear
  //       placeholder='Select'
  //       className='select'
  //       defaultValue={value || ''}
  //       dropdownMatchSelectWidth={false}
  //       onChange={(value) => props.handleSelectRegex(index, value || '')}
  //     >
  //       {
  //         regexList.map(regex => <Option value={regex}>{regex}</Option>)
  //       }
  //     </Select> : <div>ahdbjh</div>)
  // }
  render: (value, rowData, index) => ['string', 'text'].includes(rowData.type) &&
    <Select
      allowClear
      placeholder='Select'
      className='select'
      defaultValue={value}
      dropdownMatchSelectWidth={false}
      onChange={(value) => props.handleSelectRegex(index, value)}
    >
      {
        regexList.map(regex => <Option key={regex} value={regex}>{regex}</Option>)
      }
    </Select>
},
{
  title: 'Action',
  key: 'action',
  render: (_, row, index) => <div className='delete' onClick={() => props.handleAttributeDelete(index, row)}>Delete</div>
},
{
  title: 'Userguideline',
  key: 'metadata',
  render: (_, row, index) => (
    <div>
      {
      props.showViewOption(row)
        ? <div className='view' onClick={() => props.handleGuidelineAction(index, row, 'view')}>View/</div>
        : <div className='create' onClick={() => props.handleGuidelineAction(index, row, 'create')}>Create new/</div>
    }
      <div className='select_from_existing' onClick={() => props.handleGuidelineAction(index, row, 'select_from_existing')}>Use existing</div>
    </div>
  )
}
]

