import React, { Component } from 'react'
import { DisplayQuestionStyle } from '../index.style'
import { RenderInput } from './renderInput'
import { Button, Divider, Row } from 'antd'

const characters = ['a', 'b', 'c', 'd', 'e']

class DisplayQuestion extends Component {
  constructor (props) {
    super(props)
    this.state = {
      currentData: {},
      childQuestions: [],
      showNextButton: false,
      responsesProvided: {},
      showPolicyWebhookList: true,
      showClaimWebhookList: true
    }
  }

  componentDidMount () {
    const { question } = this.props
    this.setState({ currentData: question, childQuestions: [] })
    this.checkForChildQuestion(question, 0)
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      question
    } = nextProps
    const { currentData } = this.state
    if (currentData.id !== question.id) {
      this.setState({ currentData: question, childQuestions: [] }, () => this.checkForChildQuestion(question, 0))
    }
  }

  checkForChildQuestion = (question, index) => {
    const { childQuestions } = this.state
    const { default_answer: defaultAnswer, possible_answers: possibleAnswers } = question

    if (defaultAnswer !== null && defaultAnswer !== undefined) {
      const childAnswerKeys = Object.keys(question.child_questions || {})
      if (childAnswerKeys.includes(defaultAnswer)) {
        childQuestions.push(question.child_questions[defaultAnswer])
        this.setState({ childQuestions, showNextButton: false })
        this.checkForChildQuestion(question.child_questions[defaultAnswer], index + 1)
      } else if (Object.keys(possibleAnswers).length === 0 && Object.keys(question.child_questions).length > 0) {
        childQuestions.push(question.child_questions[Object.keys(question.child_questions)[0]])
        this.setState({ childQuestions, showNextButton: false })
        this.checkForChildQuestion(question.child_questions[Object.keys(question.child_questions)[0]], index + 1)
      } else {
        childQuestions.splice(index)
        this.setState({ childQuestions, showNextButton: true })
      }
    }
  }

  findAndReplaceKey = (data, id, text) => {
    if (data.id === id) {
      data.default_answer = text
    } else {
      if (!data.child_questions[data.default_answer]) {
        this.findAndReplaceKey(data.child_questions[Object.keys(data.child_questions)[0]], id, text)
      } else {
        this.findAndReplaceKey(data.child_questions[data.default_answer], id, text)
      }
    }
  }

  handleInputChange = (id, value) => {
    const { currentData, responsesProvided } = this.state
    this.findAndReplaceKey(currentData, id, value)
    this.setState({ responsesProvided, childQuestions: [] })
    this.setState({ currentData }, () => this.checkForChildQuestion(currentData, 0))
  }

  toggleState = (stateName) => {
    this.setState({ [stateName]: !this.state[stateName] })
  }

  handleNext = () => {
    const { currentData } = this.state
    this.props.onHandleNext(currentData)
  }

  renderQuestion = (question = {}, index = '') => {
    const { policyFieldList = [], claimFieldList = [], policyFormAttributeMultipleProduct, source, serviceCenterList } = this.props
    const { showPolicyWebhookList, showClaimWebhookList } = this.state
    const {
      id,
      label,
      name,
      description,
      answer_type: answerType,
      default_answer: defaultAnswer,
      possible_answers: possibleAnswers
    } = question

    return (
      <div className='question-wrapper' key={id + label}>
        <div className='question'>
          Question {index}: {label}
        </div>
        <div className='description'>
          {description}
        </div>
        <Row type='flex' className='input'>
          <div className='response-heading'>Response: </div>
          {RenderInput(this,
            id,
            answerType,
            possibleAnswers,
            defaultAnswer,
            name,
            policyFieldList,
            claimFieldList,
            serviceCenterList,
            showPolicyWebhookList,
            showClaimWebhookList,
            policyFormAttributeMultipleProduct,
            source
          )}
        </Row>
      </div>
    )
  }

  render () {
    const { lastQuestion, currentQuestion } = this.props
    const { currentData = {}, childQuestions, showNextButton } = this.state

    return (
      <DisplayQuestionStyle>
        {/* Parent Question */}
        {this.renderQuestion(currentData, currentQuestion + 1)}

        {
          childQuestions.length > 0 &&
            <Divider />
        }

        {/* Child Questions */}
        {
          childQuestions.map((question, index) => this.renderQuestion(question, characters[index]))
        }

        <Row type='flex' justify='space-between'>
          <Button
            disabled={currentData.us_id === '1'}
            onClick={this.props.onHandlePrevious}
          >
            Previous
          </Button>
          <Button
            type='primary'
            disabled={!showNextButton}
            onClick={this.handleNext}
          >
            {lastQuestion ? 'Review' : 'Next'}
          </Button>
        </Row>

      </DisplayQuestionStyle>
    )
  }
}

export default DisplayQuestion
