import React, { Component } from 'react'
import { Progress } from 'antd'
import { connect } from 'react-redux'
import { QuestionnaireStyle } from './index.style'
import ClaimsAction from '../../../../redux/claims/actions'
import QuestionHandler from './QuestionnaireComponents/handleQuestion'

const { getConfigTemplateDetails, getConfigTemplateSubmit } = ClaimsAction

class Questionnaire extends Component {
  constructor (props) {
    super(props)
    this.state = {
      percent: 0,
      questionnaireData: this.props.responsesProvided || {},
      inprogess: {},
      editData: {},
      configState: '',
      responsesProvided: this.props.responsesProvided || {},
      questions: this.props.questions || []
    }
  }

  componentDidMount () {
    const { configState } = this.props
    if (configState === 'INPROGRESS') {
      this.handleInprogress()
    }
  }

  handleInprogress = () => {
    const { responsesProvided, questions } = this.props
    const percent = ((Object.keys(responsesProvided).length) / questions.length) * 100
    this.handleProgressBar(percent)
  }

  findAndReplaceKey = (data, name, text) => {
    if (data.name === name) {
      data.default_answer = text
    } else {
      this.findAndReplaceKey(data.child_questions[data.default_answer], name, text)
    }
  }

  handleProgressBar = (percent) => {
    this.setState({ percent: parseFloat(percent).toFixed(2) })
  }

  handleQuestionnaireSubmit = (questionnaireData) => {
    this.setState({ questionnaireData })
    this.props.saveQuestionnaireData(questionnaireData)
    this.props.handleNext()
  }

  render () {
    const {
      benefitId, configData, questions = [], inprogess, responsesProvided, configState, inprogressConfig, source,
      configDumpId
    } = this.props
    const { percent, questionnaireData } = this.state

    return (
      <QuestionnaireStyle>
        <Progress percent={percent} />
        <QuestionHandler
          questions={questions}
          onHandleProgressBar={this.handleProgressBar}
          onHandleQuestionnaireSubmit={this.handleQuestionnaireSubmit}
          benefitId={benefitId}
          configData={configData}
          questionnaireData={questionnaireData}
          responsesProvided={responsesProvided}
          id={655}
          inprogessData={inprogess}
          configState={configState}
          inprogressConfig={inprogressConfig}
          onHandlePrevious={this.props.handlePrevious}
          source={source}
          configDumpId={configDumpId}
          hideBackToFormButton
        />
      </QuestionnaireStyle>
    )
  }
}

export default connect(state => ({
  claimsConfigTemplatesDetails: state.Claims.claimsConfigTemplatesDetails
}), {
  getConfigTemplateDetails,
  getConfigTemplateSubmit
})(Questionnaire)
