import React, { Component } from 'react'
import _ from 'lodash'
import { connect } from 'react-redux'
import { withRouter } from 'react-router'
import { Button, Row, Col, Table, Divider, Card, notification, Spin } from 'antd'
import { ReviewStyle } from './index.style'
import ClaimsAction from '../../../../redux/claims/actions'
import LoadingActions from '../../../../../redux/loading/actions'
import ErrorActions from '../../../../../redux/error/actions'
import { ReviewFormColumns } from './data'
import moment from 'moment'
import QueryString from 'query-string'

const {
  getConfigTemplateSubmit,
  updateConfig,
  resetConfigDumpId,
  submitAutoApprovalConfig,
  resetReduxStateClaim
} = ClaimsAction
const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions

const renderAnswer = (ans) => {
  if (Array.isArray(ans)) {
    return ans.join(',')
  }

  if (typeof ans === 'number') {
    return ans
  }
  if (moment.isDate(ans)) {
    return moment(ans).format('YYYY-MM-DD')
  }

  if (ans.endsWith('.000Z')) {
    return ans.substring(0, 10)
  }
  return ans
}

class Review extends Component {
  constructor (props) {
    super(props)
    this.state = {
      configData: [],
      data: undefined
    }
  }

  componentDidMount () {
    const { configData } = this.props
    this.handleConfigData(configData)
    this.props.resetLoadingRedux(['GET_CLAIM_CONFIG_TEMPLATE_SUBMIT'])
    this.props.resetErrorRedux(['GET_CLAIM_CONFIG_TEMPLATE_SUBMIT'])
    this.props.resetLoadingRedux(['SUBMIT_AUTO_APPROVAL_CONFIG'])
    this.props.resetErrorRedux(['SUBMIT_AUTO_APPROVAL_CONFIG'])
  }

  handleConfigData = (configData) => {
    let responses = []
    configData.forEach((data) => {
      const { id, label, default_answer: defaultAnswer, child_questions: childQuestions } = data
      responses[id] = {
        ques: label,
        ans: defaultAnswer,
        id
      }
      responses = this.updateChildResponse(responses, childQuestions, data)
    })
    this.setState({ configData: responses.filter((val) => !!val), data: configData })
  }

  updateChildResponse = (responses = [], childQuestions = {}, data = {}) => {
    if (!childQuestions || !Object.keys(childQuestions).length) {
      return responses
    }

    if (!Object.hasOwn(childQuestions, data.default_answer)) {
      return responses
    }

    const { default_answer: defaultAnswer, id, child_questions: childquestions, label } = childQuestions[data.default_answer]
    if (defaultAnswer !== null && defaultAnswer !== undefined && defaultAnswer !== '' && data.default_answer) {
      responses[id] = {
        ques: label,
        ans: defaultAnswer,
        id
      }
      responses = this.updateChildResponse(responses, childquestions, childQuestions[data.default_answer])
    }

    return responses
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      submitConfigLoading,
      submitConfigError,
      submitClaimConfigStatus,
      updateConfigLoading,
      updateConfigError,
      updateConfigStatus,
      source,
      submitAutoApprovalConfigStatus,
      submitAutoApprovalConfigError,
      submitAutoApprovalConfigLoading,
      resetReduxStateClaim,
      configData
    } = nextProps

    if (['auto_approval', 'green_channel'].includes(source)) {
      if (submitAutoApprovalConfigLoading === false) {
        notification[submitAutoApprovalConfigError ? 'error' : 'success']({ message: submitAutoApprovalConfigStatus })
        if (submitAutoApprovalConfigError === false) {
          this.props.resetConfigDumpId()
          resetReduxStateClaim(['validationData'])
          this.props?.history?.push && (
            source === 'auto_approval'
              ? this.props.history.push('/claims/instant-claim-configuration')
              : this.props.history.push('/claims/green-channel-config')
          )
        }
      }
    } else {
      if (submitConfigLoading === false) {
        notification[submitConfigError ? 'error' : 'success']({ message: submitClaimConfigStatus })
        if (submitConfigError === false) {
          this.props.resetConfigDumpId()
          this.props.history.goBack()
        }
        this.props.resetLoadingRedux(['GET_CLAIM_CONFIG_TEMPLATE_SUBMIT'])
        this.props.resetErrorRedux(['GET_CLAIM_CONFIG_TEMPLATE_SUBMIT'])
      }

      if (updateConfigLoading === false) {
        notification[updateConfigError ? 'error' : 'success']({ message: updateConfigStatus })
        if (updateConfigError === false) {
          this.props.resetConfigDumpId()
          this.props.history.goBack()
        }
        this.props.resetLoadingRedux(['UPDATE_CONFIG'])
        this.props.resetErrorRedux(['UPDATE_CONFIG'])
      }

      if (!_.isEqual(configData, this.state.data)) {
        this.setState({ data: configData })
        this.handleConfigData(configData)
      }
    }
  }

  getResponseKey = (data, responses, label = 'label') => {
    if (moment.isMoment(data.default_answer)) {
      data.default_answer = moment(data.default_answer).format('YYYY-MM-DD')
    }
    responses[data[label]] = data.default_answer

    if (Object.keys(data.possible_answers).length === 0 && Object.keys(data.child_questions).length > 0 && !data.child_questions[data.default_answer]) {
      return this.getResponseKey(data.child_questions[Object.keys(data.child_questions)[0]], responses, label)
    }
    if (Object.keys(data.child_questions).length === 0 || !data.child_questions[data.default_answer]) {
      return responses
    } else {
      this.getResponseKey(data.child_questions[data.default_answer], responses, label)
    }
  }

  handleSubmit = () => {
    const {
      validationData,
      configSlug,
      inprogressConfig,
      source,
      partnerProductKey,
      submitAutoApprovalConfig,
      providerId,
      autoApprovalConfigId,
      benefitId,
      packageList
    } = this.props
    if (['auto_approval', 'green_channel'].includes(source)) {
      const packages = []

      for (const key in packageList) {
        const list = packageList[key].map((packageObject) => packageObject?.package_code)
        packages.push(...list)
      }

      const payload = {
        provider_id: providerId.code,
        partner_product_key: partnerProductKey && partnerProductKey.map((product) => `${product.partner}-${product.name}`),
        product_keys: partnerProductKey && partnerProductKey.map((partnerProduct) => partnerProduct.name),
        packages: packages,
        config_dump_id: validationData.config_dump_id || null,
        benefits: benefitId.map((b) => b.id)
      }

      if (source === 'auto_approval') {
        payload.auto_approval_config_id = autoApprovalConfigId || null
        submitAutoApprovalConfig(payload, source)
      } else if (source === 'green_channel') {
        const { search } = this.props.history.location || {}
        const query = QueryString.parse(search) || {}
        const { configId } = query
        payload.custom_claim_flow_config_id = Number(configId)
        payload.source = source
        submitAutoApprovalConfig(payload, source)
      }
    } else {
      if (configSlug) {
        this.props.updateConfig({
          body: {
            config_slug: configSlug,
            last_updated_source: 'control-panel'
          }
        })
      } else {
        this.props.getConfigTemplateSubmit({
          body: {
            config_dump_id: (validationData && validationData.config_dump_id) || (inprogressConfig && inprogressConfig.config_dump_id),
            last_updated_source: 'control-panel'
          }
        })
      }
    }
  }

  renderRow = (key, value) => {
    return (
      <Row className='form-row'>
        <Col span={8} className='form-label'>{key}</Col>
        <Col span={16}>{value}</Col>
      </Row>
    )
  }

  render () {
    const { formData = [], submitConfigLoading, submitAutoApprovalConfigLoading } = this.props
    const { configData = [] } = this.state

    return (
      <ReviewStyle>
        <Spin spinning={!!(submitConfigLoading || submitAutoApprovalConfigLoading)}>
          <div className='heading'>Responses</div>
          {
            formData.length
              ? (
                <Card className='form-container'>
                  <div className='form-heading'>FORMS</div>
                  {
                    formData.map((form, index) => (
                      <div key={index}>
                        {this.renderRow('Title', form.title)}
                        {this.renderRow('Description', form.description)}
                        <Table
                          dataSource={form.attributes}
                          columns={ReviewFormColumns}
                          pagination={false}
                          rowKey='master_attribute_id'
                        />
                        <Divider />
                      </div>
                    ))
                  }
                </Card>
                )
              : null
          }
          <div className='form-heading'>QUESTIONNAIRE</div>
          <div className='review-container'>
            {
              configData.map(({ ques, ans, id }, index) =>
                <Row className='review-row' key={id}>
                  <Col span={20} className='review-label'>{ques}</Col>
                  <Col span={4} className='review-value'>
                    {renderAnswer(ans)}
                  </Col>
                </Row>
              )
            }
          </div>
          <Row type='flex' justify='space-between' className='button'>
            <Button
              type='danger'
              onClick={this.props.handlePrevious}
            >
              Back (Questionnaire)
            </Button>
            <Button
              type='primary'
              onClick={this.handleSubmit}
            >
              Submit
            </Button>
          </Row>
        </Spin>
      </ReviewStyle>
    )
  }
}

export default connect(state => ({
  validationData: state.Claims.claimConfigDumpId,

  submitConfigLoading: state.Loading.GET_CLAIM_CONFIG_TEMPLATE_SUBMIT,
  submitConfigError: state.Error.GET_CLAIM_CONFIG_TEMPLATE_SUBMIT,
  submitClaimConfigStatus: state.Claims.submitClaimConfigStatus,

  updateConfigLoading: state.Loading.UPDATE_CONFIG,
  updateConfigError: state.Error.UPDATE_CONFIG,
  updateConfigStatus: state.Claims.updateConfigStatus,

  submitAutoApprovalConfigLoading: state.Loading.SUBMIT_AUTO_APPROVAL_CONFIG,
  submitAutoApprovalConfigError: state.Error.SUBMIT_AUTO_APPROVAL_CONFIG,
  submitAutoApprovalConfigStatus: state.Claims.submitAutoApprovalConfigStatus,

  packageList: state.Claims.packageListOnMultipleProduct
}), {
  getConfigTemplateSubmit,
  resetLoadingRedux,
  resetErrorRedux,
  updateConfig,
  resetConfigDumpId,
  submitAutoApprovalConfig,
  resetReduxStateClaim
})(withRouter(Review))
