import React from 'react'
import { Radio, Input, InputNumber, Checkbox, Select, DatePicker } from 'antd'
import { compact } from 'lodash'
import moment from 'moment'
import { generatepolicyFormAttributeMultipleProduct } from '../helpers'

const { Option, OptGroup } = Select

export const RenderInput = (
  props,
  id,
  answerType,
  possibleAnswers,
  defaultAnswer,
  attributeName,
  policyFieldsList = [],
  claimFieldsList = [],
  serviceCenterList,
  showPolicyWebhookList,
  showClaimWebhookList,
  policyFormAttributeMultipleProduct,
  source) => {
  switch (answerType) {
    case 'boolean':
      return (
        <Radio.Group
          key={id}
          onChange={(e) => props.handleInputChange(id, e.target.value)}
          defaultValue={defaultAnswer}
        >
          {
          Object.keys(possibleAnswers).map((key) =>
            <Radio value={key} key={key}>{possibleAnswers[key]}</Radio>)
        }
        </Radio.Group>
      )
    case 'integer':
      return (
        <InputNumber
          key={id}
          onBlur={(e) => props.handleInputChange(id, e.target.value && parseInt(e.target.value))}
          defaultValue={defaultAnswer}
          min={0}
        />
      )
    case 'multiple-choice':
      if (attributeName === 'service-center-selected') {
        return (
          <div>
            <Select
              key={id}
              showSearch
              style={{ width: 300 }}
              placeholder='Select...'
              dropdownMatchSelectWidth={false}
              optionFilterProp='children'
              disabled={!showPolicyWebhookList}
              mode='multiple'
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              defaultValue={defaultAnswer || []}
              onChange={value => {
                value = compact(value)
                props.handleInputChange(id, value)
              }}
            >
              {serviceCenterList.filter(({ is_active: isActive }) => !!isActive).map(({ code, name }) => <Option key={code} value={code}>{name}</Option>)}
            </Select>
          </div>
        )
      }
      if (attributeName === 'web-hook-keys-from-policy') {
        return (
          <div>
            <Select
              key={id}
              showSearch
              style={{ width: 300 }}
              placeholder='Select...'
              dropdownMatchSelectWidth={false}
              optionFilterProp='children'
              disabled={!showPolicyWebhookList}
              mode='multiple'
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              defaultValue={defaultAnswer || []}
              onChange={value => {
                value = compact(value)
                props.handleInputChange(id, value)
              }}
            >
              {
              policyFieldsList.map((value) => <Option key={value} value={value}>{value}</Option>)
            }
            </Select>
            <Checkbox
              key={id}
              onChange={value => {
                if (value) {
                  props.toggleState('showPolicyWebhookList')
                  props.handleInputChange(id, [])
                }
              }}
              value={!showPolicyWebhookList}
              checked={!showPolicyWebhookList}
            >
              No Policy Field to be selected
            </Checkbox>
          </div>
        )
      } else if (attributeName === 'web-hook-keys-from-claim') {
        return (
          <div>
            <Select
              key={id}
              showSearch
              style={{ width: 300 }}
              placeholder='Select...'
              dropdownMatchSelectWidth={false}
              optionFilterProp='children'
              mode='multiple'
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              disabled={!showClaimWebhookList}
              defaultValue={defaultAnswer || []}
              onChange={value => props.handleInputChange(id, value)}
            >
              {
              claimFieldsList.map(({ name, label }) => <Option key={name} value={name}>{label}</Option>)
            }
            </Select>
            <Checkbox
              key={id}
              onChange={value => {
                if (value) {
                  props.toggleState('showClaimWebhookList')
                  props.handleInputChange(id, [])
                }
              }}
              value={!showClaimWebhookList}
              checked={!showClaimWebhookList}
            >
              No Claims Field to be selected
            </Checkbox>
          </div>
        )
      } else {
        return (
          <Checkbox.Group
            key={id}
            onChange={(value) => props.handleInputChange(id, value)}
            defaultValue={defaultAnswer}
          >
            {
            Object.keys(possibleAnswers).map((key) =>
              <Checkbox key={key} value={key}>{possibleAnswers[key]}</Checkbox>)
          }
          </Checkbox.Group>
        )
      }
    case 'single-choice':
      if (['Y-percentage-of-X-field-from-policy-value', 'Y-percentage-of-X-price-field-from-policy'].includes(attributeName)) {
        if (['auto_approval'].includes(source)) {
          const policyFormAttributes = generatepolicyFormAttributeMultipleProduct(policyFormAttributeMultipleProduct)
          return (
            <Select
              style={{ width: 300 }}
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              showSearch
              dropdownMatchSelectWidth={false}
              onChange={value => props.handleInputChange(id, value.join(','))}
              mode='multiple'
              defaultValue={(defaultAnswer && typeof defaultAnswer === 'string' && defaultAnswer.split(',')) || []}
            >
              {policyFormAttributes.map((attribute) => (
                <OptGroup label={attribute.label} key={attribute.label}>
                  {attribute.options.map(({ label, value }) => (
                    <Option value={value} key={label}>
                      {label}
                    </Option>
                  ))}
                </OptGroup>)
              )}
            </Select>
          )
        }
        return (
          <Select
            key={id}
            showSearch
            style={{ width: 300 }}
            placeholder='Select...'
            dropdownMatchSelectWidth={false}
            optionFilterProp='children'
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            defaultValue={defaultAnswer}
            onChange={value => props.handleInputChange(id, value)}
          >
            {
            policyFieldsList.map((value) => {
              return <Option key={value} value={value}>{value}</Option>
            })
          }
          </Select>
        )
      }
      if (attributeName === 'Y-percentage-of-X-field-from-claim-value' || attributeName === 'X-field-from-claim-value') {
        return (
          <Select
            key={id}
            showSearch
            style={{ width: 300 }}
            placeholder='Select...'
            dropdownMatchSelectWidth={false}
            optionFilterProp='children'
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            defaultValue={defaultAnswer}
            onChange={value => props.handleInputChange(id, value)}
          >
            {
            claimFieldsList.map(({ name, label }) => <Option key={name} value={name}>{label}</Option>)
          }
          </Select>
        )
      }
      if (attributeName === 'incident-date-key-selected') {
        return (
          <Select
            key={id}
            showSearch
            style={{ width: 300 }}
            placeholder='Select...'
            dropdownMatchSelectWidth={false}
            optionFilterProp='children'
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            defaultValue={defaultAnswer}
            onChange={value => props.handleInputChange(id, value)}
          >
            {
            claimFieldsList.filter(({ type }) => type === 'date').map(({ name, label }) => <Option key={name} value={name}>{label}</Option>)
          }
          </Select>
        )
      }
      if (['claim-amount-x-percentage-of-policy-field', 'Y-range-of-X-price-field-from-policy'].includes(attributeName)) {
        if (['auto_approval'].includes(source)) {
          const policyFormAttributes = generatepolicyFormAttributeMultipleProduct(policyFormAttributeMultipleProduct)
          return (
            <Select
              style={{ width: 300 }}
              showSearch
              dropdownMatchSelectWidth={false}
              onChange={value => props.handleInputChange(id, value.join(','))}
              mode='multiple'
              optionFilterProp='children'
              defaultValue={(defaultAnswer && typeof defaultAnswer === 'string' && defaultAnswer.split(',')) || []}
              filterOption={(input, option) => {
                const { children } = option.props

                if (option.type.isSelectOptGroup) {
                  return children.includes(child => child.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0)
                }
                return children.toLowerCase().indexOf(input.toLowerCase()) >= 0
              }}
            >
              {policyFormAttributes.map((attribute) => (
                <OptGroup label={attribute.label} key={attribute.label}>
                  {attribute.options.map(({ label, value }) => (
                    <Option value={value} key={label}>
                      {label}
                    </Option>
                  ))}
                </OptGroup>)
              )}
            </Select>
          )
        }
        return (
          <Select
            key={id}
            showSearch
            style={{ width: 300 }}
            placeholder='Select...'
            dropdownMatchSelectWidth={false}
            optionFilterProp='children'
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            defaultValue={defaultAnswer}
            onChange={value => props.handleInputChange(id, value)}
          >
            {
            policyFieldsList.map((value) => {
              return <Option key={value} value={value}>{value}</Option>
            })
          }
          </Select>
        )
      }
      return (
        <Radio.Group
          key={id}
          onChange={(e) => props.handleInputChange(id, e.target.value)}
          defaultValue={defaultAnswer}
        >
          {
          Object.keys(possibleAnswers).map((key) =>
            <Radio
              className='single-choice' value={key} key={key}
            >{possibleAnswers[key]}
            </Radio>)
        }
        </Radio.Group>
      )

    case 'date':
      return (
        <DatePicker
          key={id}
          onChange={(date) => props.handleInputChange(id, new Date(moment(date).format('YYYY-MM-DD[T]HH:mm:ss')))}
          defaultValue={defaultAnswer ? moment(moment(defaultAnswer).format('YYYY-MM-DD')) : undefined}
        />
      )
    default:
      return (
        <Input
          key={id}
          onBlur={(e) => props.handleInputChange(id, e.target.value)}
          defaultValue={defaultAnswer}
        />
      )
  }
}
