import React, { Component } from 'react'
import { connect } from 'react-redux'
import _, { get } from 'lodash'
import { notification, Spin, Button, Divider } from 'antd'
import { HandleQuestionStyle } from '../index.style'
import DisplayQuestion from './displayQuestion'
import ClaimsAction from '../../../../../redux/claims/actions'
import ServiceCenterActions from '../../../../../redux/serviceCenter/actions'
import LoadingActions from '../../../../../../redux/loading/actions'
import ErrorActions from '../../../../../../redux/error/actions'
import { withRouter } from 'react-router'

const { getServiceCenterList } = ServiceCenterActions
const { getConfigTemplateValidation } = ClaimsAction
const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions

class HandleQuestion extends Component {
  constructor (props) {
    super(props)
    this.state = {
      currentQuestion: 0,
      questions: props.questions || [],
      responsesProvided: props.responsesProvided || {},
      questionnaireData: {}
    }
  }

  componentDidMount () {
    const { responsesProvided, configState, questionnaireData, questions } = this.props
    this.setState({ questions })
    if (configState === 'INPROGRESS') {
      const responseLength = Object.keys(responsesProvided).length
      this.setState({
        currentQuestion: responseLength < questions.length ? responseLength : questions.length - 1,
        questionnaireData,
        responsesProvided: questionnaireData
      })
    }
    this.props.resetLoadingRedux(['GET_CONFIG_TEMPLATES_VALIDATIONS'])
    this.props.resetErrorRedux(['GET_CONFIG_TEMPLATES_VALIDATIONS'])
    const state = this.props.location.state || {}
    const { benefitSource } = state
    this.props.getServiceCenterList({ source: benefitSource })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      validationLoading,
      validationError,
      claimConfigDumpIdMessage,
      questionnaireData
    } = nextProps
    const {
      currentQuestion,
      questions
    } = this.state

    if (validationLoading === false) {
      if (!validationError) {
        notification.success({ message: 'Response Validated' })
        const questionsLength = questions.length
        if (questionsLength === currentQuestion + 1) {
          this.props.onHandleQuestionnaireSubmit(questions)
        } else {
          this.props.onHandleProgressBar(((currentQuestion + 1) / questionsLength) * 100)
          this.setState({ questions, currentQuestion: currentQuestion + 1 })
        }
      } else {
        notification.error({ message: claimConfigDumpIdMessage })
      }
      this.props.resetLoadingRedux(['GET_CONFIG_TEMPLATES_VALIDATIONS'])
      this.props.resetErrorRedux(['GET_CONFIG_TEMPLATES_VALIDATIONS'])
    }

    if (this.props.configState === 'INPROGRESS' && questionnaireData && !_.isEqual(questionnaireData, this.state.questionnaireData)) {
      this.setState({ questionnaireData, currentQuestion: Object.keys(questionnaireData).length, responsesProvided: questionnaireData })
    }
  }

  getResponseKey = (data, responses, label = 'name') => {
    responses[data[label]] = data.default_answer

    if (Object.keys(data.possible_answers).length === 0 && Object.keys(data.child_questions).length > 0 && !data.child_questions[data.default_answer]) {
      return this.getResponseKey(data.child_questions[Object.keys(data.child_questions)[0]], responses, label)
    }
    if (Object.keys(data.child_questions).length === 0 || !data.child_questions[data.default_answer]) {
      return responses
    } else {
      this.getResponseKey(data.child_questions[data.default_answer], responses, label)
    }
  }

  handleNext = (data) => {
    const { claimsConfigTemplatesDetails, benefitId, validationData, inprogressConfig, source, configDumpId } = this.props
    const { responsesProvided, currentQuestion } = this.state
    if (!responsesProvided) {
      responsesProvided[data.us_id] = {}
    }
    const responses = {}
    this.getResponseKey(data, responses, 'name')
    responsesProvided[data.us_id] = responses

    this.props.getConfigTemplateValidation({
      body: {
        responses_provided: responsesProvided,
        current_pointer: currentQuestion + 1,
        template_id: claimsConfigTemplatesDetails.template_id || inprogressConfig.template_id,
        template_version_id: claimsConfigTemplatesDetails.template_version_id || inprogressConfig.template_version_id,
        benefit_id: !['auto_approval', 'green_channel'].includes(source) ? benefitId : undefined,
        config_dump_id: (validationData && validationData.config_dump_id) || (inprogressConfig && inprogressConfig.config_dump_id) || configDumpId
      }
    })
    this.setState({ responsesProvided })
  }

  handlePrevious = () => {
    const { currentQuestion, questions } = this.state
    this.setState({ currentQuestion: currentQuestion - 1 })
    const questionsLength = questions.length
    this.props.handleProgressBar(((currentQuestion - 1) / questionsLength) * 100)
  }

  handlePolicyAttributeList = (data, elementName = '', finalData = []) => {
    const keys = Object.keys(data)

    keys.forEach(item => {
      if (['field_type', 'type'].includes(item)) {
        return
      }
      const currentElementName = elementName ? [elementName, item].join('.') : item

      if (data[item].fields) {
        this.handlePolicyAttributeList(data[item].fields, currentElementName, finalData)
      } else {
        finalData.push(currentElementName)
      }
    })

    return finalData
  }

  render () {
    const {
      validationLoading,
      policyFormAttributes = {},
      claimConfigData = {},
      hideBackToFormButton,
      policyFormAttributeMultipleProduct,
      source,
      serviceCenterList
    } = this.props
    const { currentQuestion, questions = [] } = this.state
    return (
      <HandleQuestionStyle>
        <Spin spinning={!!validationLoading}>
          <DisplayQuestion
            key={currentQuestion}
            question={questions[currentQuestion]}
            lastQuestion={questions.length === (currentQuestion + 1)}
            onHandleNext={this.handleNext}
            onHandlePrevious={this.handlePrevious}
            currentQuestion={currentQuestion}
            serviceCenterList={serviceCenterList}
            policyFormAttributeMultipleProduct={policyFormAttributeMultipleProduct}
            policyFieldList={this.handlePolicyAttributeList(get(policyFormAttributes, 'request', {}), 'request')}
            claimFieldList={get(claimConfigData, 'selectedClaimsFormAttribute', [])}
            source={source}
          />
          <Divider />

          {!hideBackToFormButton
            ? (
              <Button
                type='danger'
                onClick={this.props.onHandlePrevious}
              >
                Back (Add Form)
              </Button>
              )
            : null}
        </Spin>
      </HandleQuestionStyle>
    )
  }
}

export default connect(state => ({
  claimsConfigTemplatesDetails: state.Claims.claimsConfigTemplatesDetails,

  validationLoading: state.Loading.GET_CONFIG_TEMPLATES_VALIDATIONS,
  validationError: state.Error.GET_CONFIG_TEMPLATES_VALIDATIONS,
  validationData: state.Claims.claimConfigDumpId,
  claimConfigDumpIdMessage: state.Claims.claimConfigDumpIdMessage,

  policyFormAttributes: state.Claims.policyFormAttributes,
  claimConfigData: state.Claims.claimConfigData,
  policyFormAttributeMultipleProduct: state.Claims.policyFormAttributeMultipleProduct,
  serviceCenterList: state.ServiceCenter.serviceCenterList
}), {
  getConfigTemplateValidation,
  getServiceCenterList,
  resetLoadingRedux,
  resetErrorRedux
})(withRouter(HandleQuestion))
